CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,phone VARCHAR(30) NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'user' CHECK(role IN('user','admin')),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,slug VARCHAR(220) UNIQUE NOT NULL,description TEXT NOT NULL,price NUMERIC(12,2) NOT NULL,original_price NUMERIC(12,2) NOT NULL,discount NUMERIC(5,2) DEFAULT 0,category_id BIGINT REFERENCES categories(id) ON DELETE RESTRICT,brand VARCHAR(120) NOT NULL,stock INT DEFAULT 0,rating NUMERIC(2,1) DEFAULT 0,review_count INT DEFAULT 0,image_url TEXT NOT NULL,cloudinary_public_id TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS product_images(id BIGSERIAL PRIMARY KEY,product_id BIGINT REFERENCES products(id) ON DELETE CASCADE,image_url TEXT NOT NULL,cloudinary_public_id TEXT);
CREATE TABLE IF NOT EXISTS cart_items(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id) ON DELETE CASCADE,quantity INT NOT NULL CHECK(quantity>0),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),total_amount NUMERIC(12,2) NOT NULL,shipping_name VARCHAR(120) NOT NULL,shipping_phone VARCHAR(30) NOT NULL,shipping_address TEXT NOT NULL,city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,pincode VARCHAR(10) NOT NULL,payment_method VARCHAR(20) NOT NULL CHECK(payment_method IN('cod','upi','card')),payment_status VARCHAR(20) DEFAULT 'pending',order_status VARCHAR(20) DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id) ON DELETE SET NULL,product_name VARCHAR(200) NOT NULL,price NUMERIC(12,2) NOT NULL,quantity INT NOT NULL,subtotal NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS banners(id BIGSERIAL PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,image_url TEXT NOT NULL,cloudinary_public_id TEXT,button_text VARCHAR(50),button_link VARCHAR(255),active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS testimonials(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,message TEXT NOT NULL,rating INT CHECK(rating BETWEEN 1 AND 5),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookings(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL,phone VARCHAR(30) NOT NULL,booking_date DATE NOT NULL,booking_time TIME NOT NULL,message TEXT,status VARCHAR(30) DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wishlist_items(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,product_id));
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id);CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);CREATE INDEX IF NOT EXISTS idx_cart_user ON cart_items(user_id);
